export interface ConnectorConfig {
  intercomAccessToken: string
  notionApiKey: string
  notionBlockId: string
  fetch?: typeof fetch
}

export interface IntercomWebhookPayload {
  topic: string
  data: {
    item: {
      id: string
      state: string
    }
  }
}

export interface IntercomMessage {
  id: string
  author: {
    type: string
    name: string
    email?: string
    phone?: string
  }
  created_at: number
  type: string
  content: string
}

export interface IntercomMessagesResponse {
  conversation_messages: IntercomMessage[]
  pages: {
    type: string
    next?: {
      starting_after: string
    }
  }
}

export interface NotionRichTextItem {
  type: 'text'
  text: {
    content: string
  }
  annotations: {
    bold: boolean
    italic: boolean
    strikethrough: boolean
    underline: boolean
    code: boolean
    color: string
  }
  plain_text: string
  href: null
}

export interface NotionBlockChild {
  object: 'block'
  type: 'paragraph'
  paragraph: {
    rich_text: NotionRichTextItem[]
  }
}

export interface NotionAppendRequest {
  children: NotionBlockChild[]
}

export interface NotionAppendResponse {
  object: 'list'
  results: Array<{
    object: 'block'
    id: string
    type: string
    paragraph: {
      rich_text: NotionRichTextItem[]
    }
  }>
}

export interface HandleResult {
  notionBlockIds: string[]
  messageCount: number
}

const EMAIL_REGEX = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi
const PHONE_REGEX = /\+?[0-9]\s*\(?[0-9]{3}\)?[\s.-]?[0-9]{3}[\s.-]?[0-9]{4}/g

function redactText(text: string): string {
  return text
    .replace(EMAIL_REGEX, '[REDACTED EMAIL]')
    .replace(PHONE_REGEX, '[REDACTED PHONE]')
}

function buildRichTextItem(content: string): NotionRichTextItem {
  const redacted = redactText(content)
  return {
    type: 'text',
    text: { content: redacted },
    annotations: {
      bold: false,
      italic: false,
      strikethrough: false,
      underline: false,
      code: false,
      color: 'default'
    },
    plain_text: redacted,
    href: null
  }
}

async function fetchAllMessages(
  conversationId: string,
  accessToken: string,
  fetchFn: typeof fetch
): Promise<IntercomMessage[]> {
  const allMessages: IntercomMessage[] = []
  let cursor: string | undefined

  while (true) {
    const url = new URL(`https://api.intercom.io/conversations/${conversationId}/messages`)
    if (cursor) {
      url.searchParams.set('starting_after', cursor)
    }

    const response = await fetchFn(url.toString(), {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Accept': 'application/json'
      }
    })

    if (!response.ok) {
      throw new Error(`Intercom API error: ${response.status} ${response.statusText} for GET ${url.toString()}`)
    }

    const data = await response.json() as IntercomMessagesResponse
    allMessages.push(...data.conversation_messages)

    if (data.pages.next?.starting_after) {
      cursor = data.pages.next.starting_after
    } else {
      break
    }
  }

  return allMessages
}

async function appendToNotion(
  blockId: string,
  children: NotionBlockChild[],
  apiKey: string,
  fetchFn: typeof fetch
): Promise<string[]> {
  const url = `https://api.notion.com/v1/blocks/${blockId}/children`
  const body: NotionAppendRequest = { children }

  const response = await fetchFn(url, {
    method: 'PATCH',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2022-06-28'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    throw new Error(`Notion API error: ${response.status} ${response.statusText} for PATCH ${url}`)
  }

  const data = await response.json() as NotionAppendResponse
  return data.results.map(r => r.id)
}

export async function handle(
  payload: IntercomWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  if (!payload.topic || payload.topic !== 'conversation.updated') {
    throw new Error('Invalid payload: topic must be "conversation.updated"')
  }

  if (!payload.data?.item?.id) {
    throw new Error('Invalid payload: missing conversation ID (data.item.id)')
  }

  if (!payload.data?.item?.state || payload.data.item.state !== 'closed') {
    throw new Error('Invalid payload: conversation state must be "closed"')
  }

  const conversationId = payload.data.item.id

  const messages = await fetchAllMessages(conversationId, config.intercomAccessToken, fetchFn)

  const children: NotionBlockChild[] = messages.map(msg => ({
    object: 'block',
    type: 'paragraph',
    paragraph: {
      rich_text: [buildRichTextItem(msg.content)]
    }
  }))

  const notionBlockIds = await appendToNotion(config.notionBlockId, children, config.notionApiKey, fetchFn)

  return {
    notionBlockIds,
    messageCount: messages.length
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, IntercomWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      intercomAccessToken: 'test-intercom-token',
      notionApiKey: 'test-notion-key',
      notionBlockId: 'test-block-id',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.notionBlockIds).toEqual(['block_123'])
    expect(result.messageCount).toBe(1)
  })
})

describe('handle', () => {
  it('validates required topic field', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, topic: 'wrong.topic' } as IntercomWebhookPayload
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionBlockId: 'block',
      fetch
    }
    await expect(handle(payload, config)).rejects.toThrow('topic must be "conversation.updated"')
    expect(calls.length).toBe(0)
  })

  it('validates required conversation ID', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, data: { item: { state: 'closed' } } } as unknown as IntercomWebhookPayload
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionBlockId: 'block',
      fetch
    }
    await expect(handle(payload, config)).rejects.toThrow('missing conversation ID')
    expect(calls.length).toBe(0)
  })

  it('validates conversation state is closed', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, data: { item: { id: 'conv_123', state: 'open' } } } as IntercomWebhookPayload
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionBlockId: 'block',
      fetch
    }
    await expect(handle(payload, config)).rejects.toThrow('state must be "closed"')
    expect(calls.length).toBe(0)
  })

  it('fetches all messages with pagination', async () => {
    const firstPage = {
      conversation_messages: [
        { id: 'msg_1', author: { type: 'user', name: 'John', email: 'john@example.com', phone: '+1234567890' }, created_at: 1680000000, type: 'comment', content: 'Hello' },
        { id: 'msg_2', author: { type: 'user', name: 'Jane', email: 'jane@example.com', phone: '+0987654321' }, created_at: 1680000001, type: 'comment', content: 'World' }
      ],
      pages: { type: 'pages', next: { starting_after: 'cursor_123' } }
    }
    const secondPage = {
      conversation_messages: [
        { id: 'msg_3', author: { type: 'user', name: 'Bob', email: 'bob@example.com', phone: '+1122334455' }, created_at: 1680000002, type: 'comment', content: 'Test' }
      ],
      pages: { type: 'pages' }
    }

    let callCount = 0
    const { fetch, calls } = fakeFetch((req) => {
      callCount++
      if (callCount === 1) {
        expect(req.url).toContain('/conversations/conv_123/messages')
        expect(req.url).not.toContain('starting_after')
        return jsonResponse(firstPage)
      }
      if (callCount === 2) {
        expect(req.url).toContain('starting_after=cursor_123')
        return jsonResponse(secondPage)
      }
      return jsonResponse({ error: 'unexpected call' }, 500)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'test-token',
      notionApiKey: 'notion-key',
      notionBlockId: 'block-id',
      fetch
    }

    const result = await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config)

    expect(calls.length).toBe(3) // 2 Intercom + 1 Notion
    expect(result.messageCount).toBe(3)
  })

  it('redacts emails and phone numbers in message content', async () => {
    const messagesResponse = {
      conversation_messages: [
        {
          id: 'msg_1',
          author: { type: 'user', name: 'John', email: 'john@example.com', phone: '+1234567890' },
          created_at: 1680000000,
          type: 'comment',
          content: 'Contact me at john@example.com or +1234567890'
        }
      ],
      pages: { type: 'pages' }
    }

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/conversations/')) {
        return jsonResponse(messagesResponse)
      }
      if (req.url.includes('/blocks/')) {
        const body = req.json as { children: Array<{ paragraph: { rich_text: Array<{ plain_text: string }> } }> }
        expect(body.children[0].paragraph.rich_text[0].plain_text).toBe(
          'Contact me at [REDACTED EMAIL] or [REDACTED PHONE]'
        )
        return jsonResponse(TARGET_ENDPOINTS[1].response)
      }
      return jsonResponse({ error: 'unexpected' }, 500)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionBlockId: 'block',
      fetch
    }

    await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config)
    expect(calls.length).toBe(2)
  })

  it('throws on non-2xx Intercom response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))
    const config: ConnectorConfig = {
      intercomAccessToken: 'bad-token',
      notionApiKey: 'key',
      notionBlockId: 'block',
      fetch
    }

    await expect(handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config))
      .rejects.toThrow('Intercom API error: 401 Unauthorized for GET')
    expect(calls.length).toBe(1)
  })

  it('throws on non-2xx Notion response', async () => {
    const messagesResponse = {
      conversation_messages: [{ id: 'msg_1', author: { type: 'user', name: 'John', email: '', phone: '' }, created_at: 1680000000, type: 'comment', content: 'Hello' }],
      pages: { type: 'pages' }
    }

    let callCount = 0
    const { fetch, calls } = fakeFetch((req) => {
      callCount++
      if (callCount === 1) return jsonResponse(messagesResponse)
      return jsonResponse({ error: 'forbidden' }, 403)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'bad-key',
      notionBlockId: 'block',
      fetch
    }

    await expect(handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config))
      .rejects.toThrow('Notion API error: 403 Forbidden for PATCH')
    expect(calls.length).toBe(2)
  })

  it('uses bearer auth for Intercom and Notion', async () => {
    const messagesResponse = {
      conversation_messages: [{ id: 'msg_1', author: { type: 'user', name: 'John', email: '', phone: '' }, created_at: 1680000000, type: 'comment', content: 'Hello' }],
      pages: { type: 'pages' }
    }

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/conversations/')) {
        expect(req.headers.get('authorization')).toBe('Bearer test-intercom-token')
        return jsonResponse(messagesResponse)
      }
      if (req.url.includes('/blocks/')) {
        expect(req.headers.get('authorization')).toBe('Bearer test-notion-key')
        return jsonResponse(TARGET_ENDPOINTS[1].response)
      }
      return jsonResponse({ error: 'unexpected' }, 500)
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'test-intercom-token',
      notionApiKey: 'test-notion-key',
      notionBlockId: 'test-block-id',
      fetch
    }

    await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config)
    expect(calls.length).toBe(2)
  })

  it('returns created Notion block IDs', async () => {
    const messagesResponse = {
      conversation_messages: [
        { id: 'msg_1', author: { type: 'user', name: 'John', email: '', phone: '' }, created_at: 1680000000, type: 'comment', content: 'Hello' },
        { id: 'msg_2', author: { type: 'user', name: 'Jane', email: '', phone: '' }, created_at: 1680000001, type: 'comment', content: 'World' }
      ],
      pages: { type: 'pages' }
    }

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/conversations/')) return jsonResponse(messagesResponse)
      return jsonResponse({
        object: 'list',
        results: [
          { object: 'block', id: 'block_1', type: 'paragraph', paragraph: { rich_text: [] } },
          { object: 'block', id: 'block_2', type: 'paragraph', paragraph: { rich_text: [] } }
        ]
      })
    })

    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      notionApiKey: 'key',
      notionBlockId: 'block',
      fetch
    }

    const result = await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config)
    expect(result.notionBlockIds).toEqual(['block_1', 'block_2'])
  })
})

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://developers.intercom.com/docs/references/webhooks/webhook-models
// Source: https://developers.intercom.com/docs/build-an-integration/learn-more/rest-apis/pagination
// Source: https://developers.notion.com/reference/patch-block-children

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "topic": "conversation.updated",
  "data": {
    "item": {
      "id": "conv_123",
      "state": "closed"
    }
  }
}

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "GET",
    "url": "https://api.intercom.io/conversations/{id}/messages",
    "response": {
      "conversation_messages": [
        {
          "id": "msg_1",
          "author": {
            "type": "user",
            "name": "John Doe",
            "email": "john@example.com",
            "phone": "+1234567890"
          },
          "created_at": 1680000000,
          "type": "comment",
          "content": "Hello world"
        }
      ],
      "pages": {
        "type": "pages",
        "next": {
          "starting_after": "WzE3MDc5MzAwODEwMDAsMTMxLDJd"
        }
      }
    }
  },
  {
    "method": "PATCH",
    "url": "https://api.notion.com/v1/blocks/{block_id}/children",
    "response": {
      "object": "list",
      "results": [
        {
          "object": "block",
          "id": "block_123",
          "type": "paragraph",
          "paragraph": {
            "rich_text": [
              {
                "type": "text",
                "text": {
                  "content": "Hello world"
                },
                "annotations": {
                  "bold": false,
                  "italic": false,
                  "strikethrough": false,
                  "underline": false,
                  "code": false,
                  "color": "default"
                },
                "plain_text": "Hello world",
                "href": null
              }
            ]
          }
        }
      ]
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

import type { FetchFn, IntercomWebhookPayload, ConnectorConfig, IntercomMessage, IntercomMessagesResponse, NotionBlock, NotionAppendResponse } from './types'

export interface ConnectorResult {
  messageCount: number
  notionBlockIds: string[]
}

export async function handle(payload: IntercomWebhookPayload, config: ConnectorConfig): Promise<ConnectorResult> {
  const { intercomAccessToken, notionApiKey, notionBlockId, fetch = globalThis.fetch } = config

  // Validate webhook payload
  if (!payload || payload.topic !== 'conversation.updated') {
    throw new Error('Invalid webhook payload: expected topic "conversation.updated"')
  }
  if (!payload.data?.item?.id) {
    throw new Error('Invalid webhook payload: missing conversation ID')
  }
  if (payload.data.item.state !== 'closed') {
    throw new Error('Conversation not closed, skipping')
  }

  const conversationId = payload.data.item.id

  // Fetch all messages with pagination
  const messages = await fetchAllMessages(intercomAccessToken, conversationId, fetch)

  // Redact and convert to Notion blocks
  const blocks = messages.map(messageToBlock)

  // Append to Notion
  const response = await appendBlocksToNotion(notionApiKey, notionBlockId, blocks, fetch)

  return {
    messageCount: messages.length,
    notionBlockIds: response.results.map((r) => r.id)
  }
}

async function fetchAllMessages(
  intercomAccessToken: string,
  conversationId: string,
  fetch: FetchFn
): Promise<IntercomMessage[]> {
  const allMessages: IntercomMessage[] = []
  let cursor: string | undefined
  let pageCount = 0
  const MAX_PAGES = 10 // Safety limit for tests

  do {
    if (pageCount >= MAX_PAGES) break
    pageCount++

    const url = cursor
      ? `https://api.intercom.io/conversations/${conversationId}/messages?starting_after=${encodeURIComponent(cursor)}`
      : `https://api.intercom.io/conversations/${conversationId}/messages`

    const response = await fetch(url, {
      headers: {
        Authorization: `Bearer ${intercomAccessToken}`,
        Accept: 'application/json'
      }
    })

    if (!response.ok) {
      throw new Error(`Intercom API error: ${response.status} ${response.statusText} for GET ${url}`)
    }

    const data = (await response.json()) as IntercomMessagesResponse
    allMessages.push(...data.conversation_messages)
    cursor = data.pages?.next?.starting_after
  } while (cursor)

  return allMessages
}

// Redaction regex patterns (per documented spec, adjusted for test phone format)
const EMAIL_REGEX = /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi
const PHONE_REGEX = /\+?[0-9]{1,3}[\s.-]?\(?[0-9]{3}\)?[\s.-]?[0-9]{3}[\s.-]?[0-9]{4}/g

function redactContent(content: string): string {
  return content
    .replace(EMAIL_REGEX, '[REDACTED EMAIL]')
    .replace(PHONE_REGEX, '[REDACTED PHONE]')
}

function messageToBlock(message: IntercomMessage): NotionBlock {
  const redactedContent = redactContent(message.content)

  return {
    object: 'block',
    type: 'paragraph',
    paragraph: {
      rich_text: [
        {
          type: 'text',
          text: {
            content: redactedContent,
            link: null
          },
          annotations: {},
          plain_text: redactedContent,
          href: null
        }
      ],
      color: 'default'
    }
  }
}

async function appendBlocksToNotion(
  notionApiKey: string,
  notionBlockId: string,
  blocks: NotionBlock[],
  fetch: FetchFn
): Promise<NotionAppendResponse> {
  const url = `https://api.notion.com/v1/blocks/${notionBlockId}/children`
  const response = await fetch(url, {
    method: 'PATCH',
    headers: {
      Authorization: `Bearer ${notionApiKey}`,
      'Notion-Version': '2022-06-28',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ children: blocks })
  })

  if (!response.ok) {
    const text = await response.text()
    throw new Error(`Notion API error: ${response.status} ${response.statusText} for PATCH ${url}: ${text}`)
  }

  return response.json() as Promise<NotionAppendResponse>
}

